import requests
import time

def fetch_email_list(api_key, url):
    """Fetches email list from the given API URL."""
    response = requests.get(url, headers={'Authorization': f'Bearer {api_key}'})
    if response.status_code == 200:
        return response.json()['email']
    return None

def send_email(email, subject, body, api_key, from_address):
    """Sends an email to the provided email address."""
    headers = {
        'Content-Type': 'application/json',
        'Subject': subject,
        'From': from_address,
        'To': email
    }
    data = {
        'to': email,
        'from': from_address,
        'body': body,
        'subject': subject,
        'priority': 'low'
    }
    response = requests.post('https://api.sendgrid.com/v3/sends', headers=headers, json=data, headers={'Content-Type': 'application/json'}, auth=('your_api_key', 'your_api_secret'))
    if response.status_code == 200:
        return True
    return False

def main():
    api_key = 'YOUR_API_KEY'
    from_address = 'your_from_address@example.com'
    email_lists = ['list1.txt', 'list2.txt', 'list3.txt']

    for email_list in email_lists:
        with open(email_list, 'r') as file:
            recipients = [line.strip() for line in file.readlines()]

        for email in recipients:
            if email:
                success = send_email(email, f'Subject: Test Email {email}', 'This is a test email. Please ignore.', api_key, from_address)
                if success:
                    print(f'Successfully sent to {email}')
                else:
                    print(f'Failed to send to {email}')

if __name__ == '__main__':
    main()
